import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/installation.md","filePath":"fr/guide/installation.md","lastUpdated":1793173149000}`),a={name:`fr/guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>Sudoku est disponible en tant qu&#39;application universelle sur l&#39;App Store : elle prend en charge iPhone, iPad et Mac avec un seul achat.</p><h2 id="telechargement" tabindex="-1">Téléchargement <a class="header-anchor" href="#telechargement" aria-label="Permalink to “Téléchargement”">​</a></h2><ul><li><strong>App Store</strong> : <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">Télécharger Sudoku</a> — application universelle pour iPhone, iPad et Mac</li></ul><h3 id="app-store-recommande" tabindex="-1">App Store (recommandé) <a class="header-anchor" href="#app-store-recommande" aria-label="Permalink to “App Store (recommandé)”">​</a></h3><p>La version de l&#39;App Store bénéficie de mises à jour automatiques et d&#39;une intégration transparente sur tous vos appareils Apple.</p><ul><li><strong>Identifiant App Store</strong> : 6793606018</li><li><strong>Lien</strong> : <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>Plateformes</strong> : iPhone, iPad, Mac (application universelle)</li><li><strong>Prix</strong> : consultez la fiche App Store pour connaître le tarif actuel</li></ul><h2 id="etapes-d-installation" tabindex="-1">Étapes d&#39;installation <a class="header-anchor" href="#etapes-d-installation" aria-label="Permalink to “Étapes d&#39;installation”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Ouvrez l&#39;<strong>App Store</strong> sur votre appareil</li><li>Recherchez « Sudoku » ou utilisez le lien direct ci-dessus</li><li>Touchez <strong>Obtenir</strong> ou <strong>Acheter</strong> pour télécharger</li><li>L&#39;application s&#39;installe automatiquement</li><li>Lancez Sudoku depuis votre écran d&#39;accueil</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Ouvrez l&#39;<strong>App Store</strong> sur votre Mac</li><li>Recherchez « Sudoku » ou utilisez le lien direct ci-dessus</li><li>Cliquez sur <strong>Obtenir</strong> ou <strong>Acheter</strong> pour effectuer l&#39;achat</li><li>L&#39;application se télécharge et s&#39;installe automatiquement</li><li>Lancez Sudoku depuis le dossier Applications ou Launchpad</li></ol><h2 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to “Premier lancement”">​</a></h2><p>Lors du premier lancement de Sudoku, l&#39;application vous demande l&#39;autorisation d&#39;accéder à iCloud (pour la synchronisation) et à Game Center (pour les classements et les succès). Ces autorisations sont facultatives : le jeu fonctionne parfaitement hors ligne sans elles.</p><h2 id="mises-a-jour" tabindex="-1">Mises à jour <a class="header-anchor" href="#mises-a-jour" aria-label="Permalink to “Mises à jour”">​</a></h2><p>Les mises à jour sont gérées automatiquement par l&#39;App Store. Pour rechercher des mises à jour manuellement, ouvrez l&#39;App Store et rendez-vous dans la section <strong>Compte → Mises à jour</strong>.</p><h2 id="desinstallation" tabindex="-1">Désinstallation <a class="header-anchor" href="#desinstallation" aria-label="Permalink to “Désinstallation”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Maintenez le doigt appuyé sur l&#39;icône de l&#39;application Sudoku</li><li>Touchez <strong>Supprimer l&#39;app</strong> → <strong>Supprimer l&#39;app</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Quittez Sudoku</li><li>Faites glisser <code>Sudoku.app</code> depuis <code>Applications</code> vers la corbeille</li><li>(Facultatif) Supprimez les données de l&#39;application :</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to “Configuration requise”">​</a></h2><ul><li><strong>iPhone/iPad</strong> : iOS/iPadOS 16.0 ou version ultérieure</li><li><strong>Mac</strong> : macOS 15.0 (Sequoia) ou version ultérieure</li><li><strong>Processeur</strong> : Apple Silicon (série M)</li><li><strong>Mémoire</strong> : 2 Go minimum</li><li><strong>Stockage</strong> : ~50 Mo</li><li><strong>Réseau</strong> : non requis pour jouer (iCloud et Game Center sont facultatifs)</li></ul><h2 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to “Dépannage”">​</a></h2><p>Si vous rencontrez des difficultés lors de l&#39;installation :</p><ul><li><strong>macOS bloque l&#39;application</strong> : ouvrez <strong>Réglages Système → Confidentialité et sécurité</strong> et cliquez sur <strong>Ouvrir quand même</strong> pour Sudoku</li><li><strong>L&#39;application n&#39;apparaît pas</strong> : redémarrez l&#39;App Store ou votre appareil, puis réessayez</li></ul><p>Pour obtenir de l&#39;aide, consultez le <a href="./troubleshooting.html">guide de dépannage</a> ou ouvrez une issue sur le dépôt du projet.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};